/**
 * Durable asset store for the AI image lab (creative engine continuation).
 *
 * `generateStudioImages` / `enhanceStudioImage` refuse to run unless the application supplies
 * an `ImageAssetStore` — their guarantee that generated bytes are never written into Neon as
 * inline data URLs. This module builds that store on top of the provider-agnostic object
 * storage contract in `lib/storage`:
 *
 *   bytes → validated → `provider.put()` under `tenants/<businessId>/image-original/…`
 *         → a `MediaAsset` metadata row holding only the durable URL + provenance.
 *
 * It is deliberately vendor-free. `resolveImageAssetStore()` returns `undefined` unless the
 * configured storage provider declares itself durable, so with no provider approved (the
 * current state — see STORAGE_DECISION.md) every route keeps failing closed with the same
 * honest 503 as before, before any quota use or provider call. The moment an approved
 * provider's adapter is switched on behind `lib/storage`, the same routes start genuinely
 * generating, editing and saving with no further code change.
 *
 * Tenant safety: the object key is derived server-side from the `businessId` the image lab
 * was already ownership-checked for; nothing client-supplied reaches the key, and the row is
 * scanned for inline image data immediately before persistence, like `/api/media` does.
 */

import { randomUUID } from "node:crypto";
import prisma from "@/lib/db";
import { parseImageDataUrl, validateImageBytes } from "@/lib/media/imageFormat";
import { containsInlineImageDataUrl } from "@/lib/media/persistence-policy";
import { checkStorageQuota, type StorageQuotaResult } from "@/lib/media/storageQuota";
import {
  assertCanStore,
  CONTENT_TYPES_BY_KIND,
  resolveDurableStorageProvider,
  type ObjectStorageProvider,
} from "@/lib/storage";
import type { ImageAssetStore, ImageAssetStoreInput, StoredAsset } from "./imageLab";

/** The slice of `prisma.mediaAsset.create` this module needs, injectable for tests. */
export type CreateMediaAsset = (data: {
  businessId: string;
  url: string;
  kind: string;
  alt: string | null;
  width: number | null;
  height: number | null;
  bytes: number | null;
  hash: string | null;
  mime: string | null;
  source: string;
  label: string | null;
  aiGenerationId: string | null;
  parentAssetId: string | null;
}) => Promise<{ id: string }>;

const defaultCreateMediaAsset: CreateMediaAsset = async (data) => {
  const asset = await prisma.mediaAsset.create({ data, select: { id: true } });
  return { id: asset.id };
};

/** Stored-file name: server-generated, matches the storage key rules, no client input. */
function storedName(prefix: string, contentType: string): string | null {
  const extension = CONTENT_TYPES_BY_KIND["image-original"][contentType];
  if (!extension) return null;
  return `${prefix}-${randomUUID()}.${extension}`;
}

/**
 * Builds an `ImageAssetStore` over one *durable* storage provider. Returns null from the
 * store (never throws) whenever bytes cannot be stored honestly, so the image lab reports
 * its existing retryable `storage_failed` outcome instead of pretending success.
 */
export function createImageAssetStore(
  provider: ObjectStorageProvider,
  createMediaAsset: CreateMediaAsset = defaultCreateMediaAsset,
  quotaCheck: (input: { businessId: string; incomingBytes: number }) => Promise<StorageQuotaResult> = checkStorageQuota,
): ImageAssetStore {
  return async (input: ImageAssetStoreInput): Promise<StoredAsset | null> => {
    if (!provider.capabilities.durable) return null;

    // Re-validate the bytes server-side: declared MIME and sniffed format must agree, and the
    // payload must be a real raster image within the upload limits (§41).
    const parsed = parseImageDataUrl(input.image.dataUrl);
    if (!parsed) return null;
    const verdict = validateImageBytes(parsed.bytes, { declaredMime: parsed.mime });
    if (verdict.status !== "ok") return null;

    // $0-first ceilings (250 MB per business, 5 GB global): never accept a write that would
    // push recorded durable usage past them. Fail-closed if usage cannot be read.
    const quota = await quotaCheck({ businessId: input.businessId, incomingBytes: parsed.bytes.length });
    if (!quota.ok) return null;

    const name = storedName("ai", verdict.facts.mime);
    if (!name) return null;

    let ref;
    try {
      assertCanStore(provider, "image-original", parsed.bytes.length);
      ref = await provider.put({
        businessId: input.businessId,
        kind: "image-original",
        name,
        contentType: verdict.facts.mime,
        body: parsed.bytes,
      });
    } catch {
      return null;
    }
    // A provider that answers with inline data (or another tenant's key) is not durable
    // storage, whatever it declared — refuse rather than persist it.
    if (/^data:/i.test(ref.url) || !ref.key.startsWith(`tenants/${input.businessId}/`)) {
      await provider.remove({ key: ref.key }).catch(() => undefined);
      return null;
    }

    const width = input.image.width > 0 ? input.image.width : verdict.facts.width;
    const height = input.image.height > 0 ? input.image.height : verdict.facts.height;
    const row = {
      businessId: input.businessId,
      url: ref.url,
      kind: "IMAGE",
      alt: input.alt,
      width,
      height,
      bytes: ref.bytes,
      hash: null,
      mime: ref.contentType,
      source: input.source,
      label: input.label,
      aiGenerationId: input.generationId,
      parentAssetId: input.parentAssetId ?? null,
    };
    if (containsInlineImageDataUrl(row)) {
      await provider.remove({ key: ref.key }).catch(() => undefined);
      return null;
    }

    try {
      const asset = await createMediaAsset(row);
      return {
        id: asset.id,
        url: ref.url,
        width,
        height,
        alt: input.alt,
        source: input.source,
        label: input.label,
        aiGenerationId: input.generationId,
      };
    } catch {
      // Metadata could not be recorded: do not leave an orphaned object behind.
      await provider.remove({ key: ref.key }).catch(() => undefined);
      return null;
    }
  };
}

/**
 * The asset store for this deployment, or `undefined` when no durable provider is configured.
 * Passing `undefined` into the image lab preserves today's fail-closed 503 exactly.
 */
export function resolveImageAssetStore(env: NodeJS.ProcessEnv = process.env): ImageAssetStore | undefined {
  const provider = resolveDurableStorageProvider(env);
  return provider ? createImageAssetStore(provider) : undefined;
}
